  EXPECT_EQ(parse_number("0xfffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0x10000000000000002", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0x10000000000000003", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0x10000000000000000", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffc", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
