  EXPECT_EQ(parse_number("0xfffffffffffffffd0000000000000000", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffc", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000001", nullptr)));
