  EXPECT_EQ(parse_number("0xfffffffffffffffe0000000000000003", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffe0000000000000000", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffefffffffffffffffc", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffefffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0xffffffffffffffff0000000000000002", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0xffffffffffffffff0000000000000003", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000000ffffffffffffffff", nullptr)));
