  EXPECT_EQ(parse_number("0xfffffffffffffffffffffffffffffffc", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000000000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffffffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000000000000000000001", nullptr)));
