  EXPECT_EQ(parse_number("0x100000000000000000000000000000000", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffefffffffffffffffffffffffffffffffe", nullptr)));
