  EXPECT_EQ(parse_number("0x1fffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000001", nullptr)));
