  EXPECT_EQ(parse_number("0x3", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0x0", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
