  EXPECT_EQ(parse_number("0xfffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0x30000000000000002", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffc0000000000000003", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffc0000000000000000", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffcfffffffffffffffc", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffcfffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0xffffffffffffffff0000000000000002", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0xffffffffffffffff0000000000000003", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0xffffffffffffffff0000000000000000", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001fffffffffffffffe", nullptr)));
