  EXPECT_EQ(parse_number("0xfffffffffffffffffffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000001", nullptr)));
