  EXPECT_EQ(parse_number("0xfffffffffffffffd0000000000000003", nullptr), parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffd0000000000000000", nullptr), parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffffffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffc", nullptr), parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000002", nullptr)));
