  EXPECT_EQ(parse_number("0x10000000000000000fffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0x100000000000000000000000000000001", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0x100000000000000000000000000000000", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0x10000000000000003ffffffffffffffff", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffcfffffffffffffffe", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffcfffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffc0000000000000001", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffc0000000000000000", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0x1ffffffffffffffffffffffffffffffff", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffffffffffffffffffe", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0x1fffffffffffffffffffffffffffffffd", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0x1ffffffffffffffff0000000000000001", nullptr), parse_number("-0xfffffffffffffffefffffffffffffffe0000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000002", nullptr)));
