  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffdfffffffffffffffd", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffc0000000000000002", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffc0000000000000003", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffc0000000000000000", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffcfffffffffffffffc", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdfffffffffffffffcfffffffffffffffd", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffdffffffffffffffff0000000000000002", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffd00000000000000000000000000000003", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffd00000000000000000000000000000000", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffd0000000000000000fffffffffffffffc", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffd0000000000000000fffffffffffffffd", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffd00000000000000030000000000000002", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffd00000000000000030000000000000003", nullptr), parse_number("-0x20000000000000002fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001ffffffffffffffff", nullptr)));
