  EXPECT_EQ(parse_number("0xfffffffffffffffefffffffffffffffefffffffffffffffd", nullptr), parse_number("-0x10000000000000001fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffeffffffffffffffff0000000000000002", nullptr), parse_number("-0x10000000000000001fffffffffffffffe", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffeffffffffffffffff0000000000000003", nullptr), parse_number("-0x10000000000000001fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr)));
