  EXPECT_EQ(parse_number("0xfffffffffffffffefffffffffffffffefffffffffffffffd", nullptr), parse_number("-0x10000000000000000fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("0xfffffffffffffffefffffffffffffffd0000000000000002", nullptr), parse_number("-0x10000000000000000fffffffffffffffe", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
