  EXPECT_EQ(parse_number("0xffffffffffffffff00000000000000000000000000000002", nullptr), parse_number("-0xffffffffffffffff0000000000000000", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("0xffffffffffffffff0000000000000000fffffffffffffffe", nullptr), parse_number("-0xffffffffffffffff0000000000000000", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("0xffffffffffffffff0000000000000000ffffffffffffffff", nullptr), parse_number("-0xffffffffffffffff0000000000000000", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
