  EXPECT_EQ(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000020000000000000002", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000020000000000000001", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff0000000000000001ffffffffffffffff", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff0000000000000001fffffffffffffffe", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001fffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000010000000000000002", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000010000000000000001", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff00000000000000010000000000000000", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffff0000000000000000ffffffffffffffff", nullptr), parse_number("0x0", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000000ffffffffffffffff", nullptr)));
