  EXPECT_EQ(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr), parse_number("0x10000000000000000", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffffffffffffffffffff", nullptr)));
