  EXPECT_EQ(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr), parse_number("0x10000000000000000", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000001", nullptr)));
