  EXPECT_EQ(parse_number("-0xfffffffffffffffe00000000000000010000000000000003", nullptr), parse_number("0x1fffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xffffffffffffffffffffffffffffffff0000000000000001", nullptr)));
