  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000000fffffffffffffffd", nullptr), parse_number("0x1fffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffeffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe00000000000000010000000000000000", nullptr), parse_number("0x1fffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffefffffffffffffffe", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe00000000000000000000000000000004", nullptr), parse_number("0x1fffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe00000000000000000000000000000003", nullptr), parse_number("0x1fffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000003fffffffffffffffe", nullptr), parse_number("0x1fffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xfffffffffffffffffffffffffffffffe0000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffefffffffffffffffcfffffffffffffffd", nullptr), parse_number("0x1fffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000002ffffffffffffffff", nullptr)));
