  EXPECT_EQ(parse_number("-0x10000000000000003ffffffffffffffff", nullptr), parse_number("0xfffffffffffffffe00000000000000020000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0x100000000000000040000000000000000", nullptr), parse_number("0xfffffffffffffffe00000000000000020000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001ffffffffffffffff", nullptr)));
  EXPECT_EQ(parse_number("-0x10000000000000003fffffffffffffffd", nullptr), parse_number("0xfffffffffffffffe00000000000000020000000000000001", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000001fffffffffffffffe", nullptr)));
