  EXPECT_EQ(parse_number("-0x1fffffffffffffffffffffffffffffffe", nullptr), parse_number("0xfffffffffffffffefffffffffffffffe0000000000000002", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000020000000000000000", nullptr)));
