  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000002", nullptr), parse_number("0xffffffffffffffffffffffffffffffff0000000000000000", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000002", nullptr)));
  EXPECT_EQ(parse_number("-0xfffffffffffffffe0000000000000001", nullptr), parse_number("0xffffffffffffffffffffffffffffffff0000000000000000", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000001", nullptr)));
  EXPECT_EQ(parse_number("-0x100000000000000000000000000000000", nullptr), parse_number("0xffffffffffffffffffffffffffffffff0000000000000000", nullptr).logical_xor(parse_number("-0xffffffffffffffff00000000000000010000000000000000", nullptr)));
  EXPECT_EQ(parse_number("-0xffffffffffffffffffffffffffffffff", nullptr), parse_number("0xffffffffffffffffffffffffffffffff0000000000000000", nullptr).logical_xor(parse_number("-0xffffffffffffffff0000000000000000ffffffffffffffff", nullptr)));
